        <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z"/></svg>
      </div>
      <div>
        <h3 class="text-lg font-bold text-amber-900 mb-2">Key Point</h3>
        <p class="text-amber-800 text-lg">Templates save time. Personalization builds trust.</p>
      </div>
    </div>
  </div>

  <!-- Action Steps -->
  <div class="bg-gradient-to-br from-emerald-50 to-teal-50 rounded-2xl p-6 border-2 border-emerald-200">
    <div class="flex items-center gap-3 mb-5">
      <div class="w-12 h-12 rounded-xl bg-emerald-100 flex items-center justify-center">
        <svg class="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4"/></svg>
      </div>
      <h3 class="text-xl font-bold text-emerald-900">Action Steps — What to Do After You Reply</h3>
    </div>
    
    <div class="space-y-4">
      
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">1</div>
        <div>
          <p class="font-semibold text-slate-900">Identify repetitive replies</p>
          <p class="text-slate-600 text-sm">What types of messages do you send over and over?</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">2</div>
        <div>
          <p class="font-semibold text-slate-900">Create one template</p>
          <p class="text-slate-600 text-sm">Write a template for your most common reply type</p>
        </div>
      </div>
      <div class="flex items-start gap-4 bg-white rounded-xl p-4 shadow-sm">
        <div class="w-10 h-10 rounded-full bg-emerald-500 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">3</div>
        <div>
          <p class="font-semibold text-slate-900">Practice personalizing</p>
          <p class="text-slate-600 text-sm">Use the template as a base, then add specific details</p>
        </div>
      </div>
    </div>
  </div>
</div>',
      title = 'Using Templates Without Sounding Robotic',
      lesson_number = 6,
      sort_order = 6,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: Using Templates Without Sounding Robotic';
  END IF;

END $$;


-- Insert Quiz Questions for Lesson: Using Templates Without Sounding Robotic

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 4 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 4 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'using-templates' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson using-templates not found in module 4';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the main risk of using templates?', 
    '["They send too quickly","They can sound cold or generic if not personalized","They cost more to send","They don''t work with mobile"]'::jsonb,
    'They can sound cold or generic if not personalized',
    'Templates save time but can feel impersonal. The key is to use them as a starting point and add personal details that show you''re paying attention.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What does ''Template first, personal touch second'' mean?', 
    '["Send the template, then send a personal message","Start with a template, then customize it with specific details","Create templates after writing personal messages","Templates are more important than personalization"]'::jsonb,
    'Start with a template, then customize it with specific details',
    'Use the template as your foundation, then add personal touches like referencing their specific question, using their name, or mentioning details from their situation.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Which of these is a good use for templates?', 
    '["Every single message should be a template","Repetitive replies like new lead responses, booking confirmations, and follow-ups","Only for complaints","Templates should never be used"]'::jsonb,
    'Repetitive replies like new lead responses, booking confirmations, and follow-ups',
    'Templates are perfect for situations where you send similar messages repeatedly - new leads, booking replies, price questions, follow-ups, etc.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
